                    del committed[key]
                    return 1, 0
                return 0, 0
            return 0, 0

        for (op, conn, key, val) in actions:
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = []
            elif op == "commit":
                for (wop, wkey, wval) in pending[conn]:
                    d, t = apply_write(conn, wop, wkey, wval)
                    changes[conn] += d
                    total[conn] += d + t
                pending[conn] = []
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = []
                in_tx[conn] = False
            elif op in ("put", "update", "delete"):
                if in_tx[conn]:
                    pending[conn].append((op, key, val))
                else:
                    d, t = apply_write(conn, op, key, val)
                    changes[conn] += d
                    total[conn] += d + t

        if cm == "changes":
            ch = changes["main"]
        elif cm == "total_main":
            ch = total["main"]
        else:
            ch = total["main"] + total["other"]
        return ch, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    trigs = ["none", "insert"]
    channel_modes = ["changes", "total_main", "total_both"]

    candidates = []
    for pm in put_modes:
        for tg in trigs:
            for cm in channel_modes:
                candidates.append((pm, tg, cm))

    def check(cand, r):
        pm, tg, cm = cand
        acts = norm_actions(r["actions"])
        obs = r["observed"]
        ch, cnt, sm = simulate(acts, pm, tg, cm)
        if obs.get("channel") != ch:
            return False
        if obs.get("committed_count") != cnt:
            return False
        if obs.get("committed_sum") != sm:
            return False
        return True

    for r in receipts:
        candidates = [c for c in candidates if check(c, r)]

    goal = context.get("goal")
    actions = norm_actions(context.get("actions", []))

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for cand in candidates:
        pm, tg, cm = cand
        ch, cnt, sm = simulate(actions, pm, tg, cm)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}

